_85:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\n#ifdef GL_ES\nprecision highp float;\n#endif\n\nuniform sampler2D u_light_texture;\nuniform sampler2D u_emissive_texture;\nuniform vec2 u_resolution;\nuniform vec3 u_ambient_color;\nuniform vec3 u_highlight_color;\nuniform float u_ambient_alpha;\nuniform float u_highlight_alpha;\nuniform float u_exposure;\nuniform float u_contrast;\nuniform float u_saturation;\nuniform float u_vignette_alpha;\nuniform float u_vignette_inner;\nuniform float u_vignette_outer;\nuniform float u_local_light_strength;\nuniform float u_local_light_glow_strength;\nuniform float u_emissive_threshold;\nuniform float u_emissive_strength;\n\nvoid main()\n{\n    vec4 source = texture2D(gm_BaseTexture, v_vTexcoord) * v_vColour;\n    vec3 base_rgb = source.rgb;\n    vec3 rgb = source.rgb;\n\n    rgb *= u_exposure;\n    rgb = ((rgb - vec3(0.5)) * u_contrast) + vec3(0.5);\n\n    float luminance = dot(rgb, vec3(0.299, 0.587, 0.114));\n    rgb = mix(vec3(luminance), rgb, u_saturation);\n\n    rgb = mix(rgb, u_ambient_color, clamp(u_ambient_alpha, 0.0, 1.0));\n    rgb += u_highlight_color * max(u_highlight_alpha, 0.0);\n\n    vec4 local_light = texture2D(u_light_texture, v_vTexcoord);\n    float local_light_amount = clamp(max(max(local_light.r, local_light.g), local_light.b) * max(u_local_light_strength, 0.0), 0.0, 1.0);\n    vec3 torch_lit_rgb = max(base_rgb, rgb) + local_light.rgb * max(u_local_light_glow_strength, 0.0);\n    rgb = mix(rgb, torch_lit_rgb, local_light_amount);\n\n    vec2 uv = v_vTexcoord;\n    vec2 pos = uv - vec2(0.5, 0.5);\n    pos.x *= u_resolution.x / max(u_resolution.y, 1.0);\n\n    float vignette_distance = length(pos);\n    float vignette_width = max(u_vignette_outer - u_vignette_inner, 0.001);\n    float vignette_inner = max(0.0, u_vignette_inner - vignette_width * 0.75);\n    float vignette_outer = u_vignette_outer + vignette_width * 0.9;\n    float vignette_t = smoothstep(vignette_inner, vignette_outer, vignette_distance);\n    float vignette = vignette_t * vignette_t * vignette_t * (vignette_t * (vignette_t * 6.0 - 15.0) + 10.0);\n    rgb = mix(rgb, vec3(0.0), clamp(vignette * u_vignette_alpha, 0.0, 1.0));\n\n    vec4 emissive = texture2D(u_emissive_texture, v_vTexcoord);\n    float emissive_mask = clamp(max(max(emissive.r, emissive.g), emissive.b), 0.0, 1.0);\n    // Explicit emissives mark world pixels that should keep their pre-lighting color.\n    rgb = mix(rgb, base_rgb, emissive_mask);\n\n    gl_FragColor = vec4(clamp(rgb, 0.0, 1.0), source.a);\n}\n",
